cssCode:
.item-wrapper {
  position: relative; width: 280px; height: 70px;
  background: #ff3333; border-radius: 12px; overflow: hidden;
  display: flex; align-items: center; justify-content: flex-end; padding-right: 20px;
  color: #fff; font-weight: bold; font-family: sans-serif;
}
.cart-item {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 100%; background: #333;
  border-radius: 12px; display: flex; align-items: center; padding-left: 20px;
  color: #fff; font-family: sans-serif; transition: transform 0.3s ease;
  touch-action: pan-y; cursor: grab;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;';

const wrapper = document.createElement('div');
wrapper.className = 'item-wrapper';
wrapper.innerText = 'DELETE';

const item = document.createElement('div');
item.className = 'cart-item';
item.innerText = 'Product Name - $99';

wrapper.appendChild(item);
c.appendChild(wrapper);

let isSwiping = false;
let sX = 0;

item.addEventListener('pointerdown', (e) => {
  isSwiping = true; sX = e.clientX;
  item.style.transition = 'none';
});
document.addEventListener('pointermove', (e) => {
  if (!isSwiping) return;
  let diffX = e.clientX - sX;
  if (diffX < -80) diffX = -80; // ડાબી બાજુ લિમિટ
  if (diffX > 0) diffX = 0; // જમણી બાજુ ન જવા દેવા
  item.style.transform = `translateX(${diffX}px)`;
});
document.addEventListener('pointerup', () => {
  if (isSwiping) {
    isSwiping = false;
    item.style.transition = 'transform 0.3s ease';
    // જો થોડું વધારે સ્વાઇપ થયું હોય તો ખુલ્લું રાખવું
    if (item.style.transform === 'translateX(-80px)') return;
    item.style.transform = `translateX(0px)`;
  }
});
